class RealProfileScreen extends StatefulWidget{const RealProfileScreen({super.key,this.onSignedOut});final VoidCallback? onSignedOut;@override State<RealProfileScreen> createState()=>_RealProfileScreenState();}
class _RealProfileScreenState extends State<RealProfileScreen>{
static const _topWarm=ui.OpenApp.lime;static const _pageSoft=Colors.white;bool busy=false,loading=true,uploadingAvatar=false,uploadingGallery=false;Map<String,dynamic> profile=const {};List<Map<String,dynamic>> questions=const [];int matchCount=0,keyCount=0;
@override void initState(){super.initState();_load();}
Future<void> _load()async{final id=OpenBackend.instance.userId;if(id==null)return;if(mounted)setState(()=>loading=true);try{final p=await OpenBackend.instance.client.from('profiles').select('id,display_name,birth_date,bio,city,avatar_url,gallery_urls,is_online,is_verified').eq('id',id).maybeSingle();final q=await OpenBackend.instance.client.from('profile_questions').select('id,question,position').eq('profile_id',id).order('position');final m=await OpenBackend.instance.activeMatches();final k=await OpenBackend.instance.client.from('key_requests').select('id').eq('receiver_id',id);if(!mounted)return;setState((){profile=p==null?<String,dynamic>{}:Map<String,dynamic>.from(p);questions=List<Map<String,dynamic>>.from(q);matchCount=m.length;keyCount=List<dynamic>.from(k).length;});}finally{if(mounted)setState(()=>loading=false);}}
int? _age(){final r=profile['birth_date']?.toString();if(r==null||r.isEmpty)return null;final b=DateTime.tryParse(r);if(b==null)return null;final n=DateTime.now();var a=n.year-b.year;if(n.month<b.month||(n.month==b.month&&n.day<b.day))a--;return a;}
void _openSettings()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>SettingsScreen(onSignedOut:widget.onSignedOut)));
void _openSecurity()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>const SecurityCenterScreen()));
Future<void> _pickAvatar()async{if(uploadingAvatar)return;final id=OpenBackend.instance.userId;if(id==null)return;try{final picked=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:88,maxWidth:1600);if(picked==null)return;if(mounted)setState(()=>uploadingAvatar=true);final bytes=await picked.readAsBytes();final ext=picked.name.toLowerCase().endsWith('.png')?'png':'jpg',path='$id/avatar.$ext';await OpenBackend.instance.client.storage.from('avatars').uploadBinary(path,bytes,fileOptions:const FileOptions(upsert:true));final url='${OpenBackend.instance.client.storage.from('avatars').getPublicUrl(path)}?v=${DateTime.now().millisecondsSinceEpoch}';await OpenBackend.instance.client.from('profiles').update({'avatar_url':url}).eq('id',id);if(mounted)setState(()=>profile={...profile,'avatar_url':url});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Fotoğraf yüklenemedi. Tekrar dene.')));}finally{if(mounted)setState(()=>uploadingAvatar=false);}}
Future<void> _pickGallery()async{if(uploadingGallery)return;final id=OpenBackend.instance.userId;if(id==null)return;try{final picked=await ImagePicker().pickMultiImage(imageQuality:88,maxWidth:1800,limit:3);if(picked.isEmpty)return;final selected=picked.take(3).toList();if(mounted)setState(()=>uploadingGallery=true);final urls=<String>[];for(var i=0;i<selected.length;i++){final x=selected[i],bytes=await x.readAsBytes();final ext=x.name.toLowerCase().endsWith('.png')?'png':'jpg',path='$id/gallery_${i+1}.$ext';await OpenBackend.instance.client.storage.from('avatars').uploadBinary(path,bytes,fileOptions:const FileOptions(upsert:true));urls.add('${OpenBackend.instance.client.storage.from('avatars').getPublicUrl(path)}?v=${DateTime.now().millisecondsSinceEpoch}');}await OpenBackend.instance.client.from('profiles').update({'gallery_urls':urls}).eq('id',id);if(mounted)setState(()=>profile={...profile,'gallery_urls':urls});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Galeri fotoğrafları yüklenemedi.')));}finally{if(mounted)setState(()=>uploadingGallery=false);}}
Future<void> _editQuestions()async{final cs=List.generate(3,(i)=>TextEditingController(text:i<questions.length?questions[i]['question']?.toString()??'':''));final saved=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,backgroundColor:Colors.white,shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(30))),builder:(c)=>Padding(padding:EdgeInsets.fromLTRB(22,22,22,MediaQuery.of(c).viewInsets.bottom+24),child:Column(mainAxisSize:MainAxisSize.min,children:[Row(children:[const Expanded(child:Text('Sorularını düzenle',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900))),IconButton(onPressed:()=>Navigator.pop(c,false),icon:const Icon(Icons.close_rounded))]),for(var i=0;i<3;i++)TextField(controller:cs[i],maxLength:90,decoration:InputDecoration(labelText:'${i+1}. soru')),SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>cs.any((x)=>x.text.trim().isEmpty)?null:Navigator.pop(c,true),child:const Text('Soruları kaydet')))])));if(saved==true){setState(()=>busy=true);try{final updated=await OpenBackend.instance.saveLockQuestions(cs.map((x)=>x.text.trim()).toList());if(mounted)setState(()=>questions=updated);}finally{if(mounted)setState(()=>busy=false);}}for(final c in cs){c.dispose();}}
Future<void> _signOut()async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Çıkış yapılsın mı?'),content:const Text('Hesabından çıkış yapacaksın. Tekrar giriş yapmak için e-posta veya telefonunu kullanabilirsin.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Çıkış yap'))]));if(ok==true){await OpenBackend.instance.signOut();if(mounted)widget.onSignedOut?.call();}}
