class _ProfileCurveClipper extends CustomClipper<Path>{@override Path getClip(Size s){final edge=s.height-48,center=s.height-8;final p=Path()..lineTo(0,edge);p.cubicTo(s.width*0.22,s.height-18,s.width*0.38,center,s.width*0.50,center);p.cubicTo(s.width*0.62,center,s.width*0.78,s.height-18,s.width,edge);p.lineTo(s.width,0);p.close();return p;}@override bool shouldReclip(covariant CustomClipper<Path> oldClipper)=>false;}
